def fetch_ids(label_id):
    ids=[]; page_token=None
    while True:
        args={"label_ids":[label_id],"include_spam_trash":False,"ids_only":True,"include_payload":False,"max_results":500}
        if page_token: args["page_token"]=page_token
        resp,err=run_composio_tool("GMAIL_FETCH_EMAILS",args)
        if err: return [],err
        data=resp.get("data",{})
        for m in (data.get("messages") or []):
            mid=m.get("id") or m.get("messageId")
            if mid: ids.append(mid)
        page_token=data.get("nextPageToken")
        if not page_token: break
    return list(dict.fromkeys(ids)),""

def apply_label(message_ids,label_id):
    for i in range(0,len(message_ids),1000):
        run_composio_tool("GMAIL_BATCH_MODIFY_MESSAGES",{"messageIds":message_ids[i:i+1000],"addLabelIds":[label_id]})
